from pathlib import Path;import moviepy;from moviepy.video.fx import BlackAndWhite, Resize;moviepy.video.io.ffmpeg_writer.ffmpeg_write_video(moviepy.VideoFileClip(f"{Path(__file__).resolve().parents[2]}/source.mp4").with_effects([Resize((150, 80))]).with_effects([BlackAndWhite()]), f"{Path(__file__).resolve().parents[1]}/outputs/grayscale_video.mp4", fps=moviepy.VideoFileClip(f"{Path(__file__).resolve().parents[2]}/source.mp4").fps); file = open(f"{Path(__file__).resolve().parents[2]}/ascii.json", 'w'); file.write("{\n"); file.write(f"  \"frameRate\": {moviepy.VideoFileClip(f"{Path(__file__).resolve().parents[2]}/source.mp4").fps},\n"); file.close(); #<-- The og java semicolon :)